CREATE TABLE IF NOT EXISTS mcp_profiles (id VARCHAR(36) PRIMARY KEY, slug VARCHAR(191) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, description TEXT NOT NULL DEFAULT '', permissions TEXT NOT NULL DEFAULT '[]', tools TEXT NOT NULL DEFAULT '[]', built_in BOOLEAN NOT NULL, enabled BOOLEAN NOT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS mcp_connections (id VARCHAR(36) PRIMARY KEY, slug VARCHAR(191) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, workspace_id VARCHAR(36) NULL REFERENCES workspaces(id), project_id VARCHAR(36) NULL REFERENCES projects(id), profile_id VARCHAR(36) NOT NULL REFERENCES mcp_profiles(id), auth_type VARCHAR(32) NOT NULL, credential_hash VARCHAR(191) NOT NULL UNIQUE, enabled BOOLEAN NOT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, last_used_at VARCHAR(40) NULL);
CREATE INDEX IF NOT EXISTS idx_mcp_connections_scope ON mcp_connections(workspace_id,project_id,enabled);
CREATE TABLE IF NOT EXISTS skill_proposals (id VARCHAR(36) PRIMARY KEY, skill_id VARCHAR(36) NOT NULL REFERENCES skills(id), base_version INTEGER NOT NULL, proposed_snapshot TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '', status VARCHAR(32) NOT NULL, created_by VARCHAR(191) NULL, reviewed_by VARCHAR(191) NULL, review_note TEXT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, reviewed_at VARCHAR(40) NULL);
CREATE INDEX IF NOT EXISTS idx_skill_proposals_status ON skill_proposals(status,skill_id,created_at);
CREATE TABLE IF NOT EXISTS execution_events (id VARCHAR(36) PRIMARY KEY, execution_id VARCHAR(36) NOT NULL REFERENCES skill_executions(id) ON DELETE CASCADE, position INTEGER NOT NULL, event_type VARCHAR(191) NOT NULL, event_data TEXT NOT NULL DEFAULT '', created_at VARCHAR(40) NOT NULL, UNIQUE(execution_id,position));
